import { 
  Group, 
  Mesh, 
  PlaneGeometry, 
  CylinderGeometry, 
  TorusKnotGeometry,
  DirectionalLight,
  Color,
} from 'three/webgpu';
import { 
  MeshStandardNodeMaterial, 
  MeshBasicNodeMaterial 
} from 'three/webgpu';
import { 
  uniform, 
  vec2,
  uv, 
  mix, 
  smoothstep,
  length,
} from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();

  // === BACKDROP WITH VERTICAL GRADIENT ===
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();

  const col0 = uniform(new Color(0x0b0b10));
  const col1 = uniform(new Color(0x101017));
  const col2 = uniform(new Color(0x16161d));

  const uvNode = uv();
  const uvY = uvNode.y;

  const grad1 = mix(col0, col1, smoothstep(uniform(0), uniform(0.7), uvY));
  const gradFinal = mix(grad1, col2, smoothstep(uniform(0.7), uniform(1), uvY));

  backdropMat.colorNode = gradFinal;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -3;
  group.add(backdrop);

  // === PEDESTAL ===
  const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 64);
  const pedestalMat = new MeshStandardNodeMaterial();
  pedestalMat.color = new Color(0x14141a);
  pedestalMat.roughness = 0.7;
  pedestalMat.metalness = 0.35;

  const pedestal = new Mesh(pedestalGeo, pedestalMat);
  pedestal.position.y = -0.6;
  group.add(pedestal);

  // === TORUS KNOT ===
  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshStandardNodeMaterial();
  knotMat.color = new Color(0xb0b0b0);
  knotMat.roughness = 0.55;
  knotMat.metalness = 0.55;
  knotMat.clearcoat = 0.22;
  knotMat.clearcoatRoughness = 0.35;
  knotMat.anisotropy = 0.9;
  knotMat.anisotropyRotation = Math.PI / 2;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      knotMat.roughnessMap = tex;
      knotMat.needsUpdate = true;
    });
  }

  const knotMesh = new Mesh(knotGeo, knotMat);
  knotMesh.position.y = 0.4;
  group.add(knotMesh);

  // === CONTACT SHADOW ===
  const shadowGeo = new PlaneGeometry(3, 3);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;

  const shadowUV = uv();
  const dist = length(shadowUV.sub(vec2(0.5, 0.5)));

  const shadowAlpha = mix(
    uniform(0.6),
    uniform(0),
    smoothstep(uniform(0), uniform(0.267), dist)
  );

  shadowMat.opacityNode = shadowAlpha;
  shadowMat.colorNode = uniform(new Color(0x000000));

  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.y = -0.36;
  shadow.rotation.x = -Math.PI / 2;
  shadow.scale.set(1.5, 1.5, 1.0);
  group.add(shadow);

  // === TEXT ===
  const headline = ctx.fontAtlas.createText('Material study 03', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
  });
  headline.position.set(0, -1.2, 0.1);
  group.add(headline);

  const caption = ctx.fontAtlas.createText('GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.44,
  });
  caption.position.set(0, -1.6, 0.1);
  group.add(caption);

  // === LIGHTING ===
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2.5, 2.5, 3);
  group.add(keyLight);

  const rimLight = new DirectionalLight(0xff6b6b, 0.8);
  rimLight.position.set(-3, 1.5, -3);
  group.add(rimLight);

  // === APPLY ORBIT PRIMITIVE ===
  let orbitCleanup = null;
  try {
    const orbitResult = ctx.primitives['orbit'](group, {
      speed: 0.1,
      radius: 0.4,
    });
    if (orbitResult && orbitResult.cleanup) {
      orbitCleanup = orbitResult.cleanup;
    }
  } catch (e) {
    console.warn('Orbit primitive error:', e);
  }

  // === CLEANUP ===
  group.userData.cleanup = () => {
    if (orbitCleanup) {
      orbitCleanup();
    }

    backdropGeo.dispose();
    backdropMat.dispose();
    pedestalGeo.dispose();
    pedestalMat.dispose();
    knotGeo.dispose();
    knotMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return group;
}
